import pickle, numpy as np, itertools, sys
X,Y=pickle.load(open('cv_data.pkl','rb'))
people=list(X.keys())
def mat(names, ppl):
    A=[]; y=[]
    for p in ppl:
        for f,yy in zip(X[p],Y[p]):
            A.append([f[n] for n in names]); y.append(yy)
    return np.array(A,float), np.array(y)
def ridge_fit(A,y,lam):
    mu=A.mean(0); sd=A.std(0)+1e-9
    Z=(A-mu)/sd
    Z1=np.hstack([Z,np.ones((len(Z),1))])
    P=lam*np.eye(Z1.shape[1]); P[-1,-1]=0
    w=np.linalg.solve(Z1.T@Z1+P, Z1.T@y)
    return (mu,sd,w)
def ridge_pred(m,A):
    mu,sd,w=m; Z=(A-mu)/sd; return np.hstack([Z,np.ones((len(Z),1))])@w
def lopo(names, lam=1.0, verbose=False):
    maes={}
    for p in people:
        tr=[q for q in people if q!=p]
        A,y=mat(names,tr); m=ridge_fit(A,y,lam)
        At,yt=mat(names,[p]); pr=ridge_pred(m,At)
        maes[p]=np.mean(np.abs(pr-yt))
    if verbose: print({k:round(v,3) for k,v in maes.items()})
    return np.mean(list(maes.values()))
if __name__=='__main__':
    sets={
     'time_only':['elapsed','sqrt_el','log_el'],
     'time+hr':['elapsed','sqrt_el','log_el','hr_now','hr_mean'],
     'time+sk':['elapsed','sqrt_el','log_el','sk_now','sk_first','sk_delta'],
     'time+hr+sk':['elapsed','sqrt_el','log_el','hr_now','hr_mean','sk_now','sk_first','sk_delta'],
     'time+hr+sk+w':['elapsed','sqrt_el','log_el','hr_now','hr_mean','sk_now','sk_first','sk_delta','w_kg','work_kg'],
     'time+hr+sk+w+anth':['elapsed','sqrt_el','log_el','hr_now','hr_mean','sk_now','sk_first','sk_delta','w_kg','work_kg','age','mass','height'],
     'time+hr+sk+w+amb':['elapsed','sqrt_el','log_el','hr_now','hr_mean','sk_now','sk_first','sk_delta','w_kg','work_kg','amb','hum'],
     'interact':['elapsed','sqrt_el','log_el','hr_now','hr_mean','sk_now','sk_first','sk_delta','w_kg','work_kg','hr_x_el','w_x_el','sk_x_el','hr_int'],
     'all':list(X[people[0]][0].keys()),
    }
    for nm,names in sets.items():
        for lam in [0.1,1,10,100]:
            print(nm, lam, round(lopo(names,lam),4))
