import json, numpy as np
from scipy.optimize import least_squares
d=json.load(open('train.json'))
people=list(d.keys())
# arrays: elapsed index 0..59 -> core
C={p:np.array([r['core_temp'] if r['core_temp'] is not None else np.nan for r in d[p]]) for p in people}
def lookup_mean(tr, stat='mean', smooth=0):
    M=np.array([C[p] for p in tr])
    if stat=='mean': v=np.nanmean(M,0)
    else: v=np.nanmedian(M,0)
    if smooth>0:
        k=np.ones(2*smooth+1)/(2*smooth+1)
        vp=np.concatenate([np.full(smooth,v[0]),v,np.full(smooth,v[-1])])
        v=np.convolve(vp,k,'valid')
    return v
def expfit(tr):
    ts=[];ys=[]
    for p in tr:
        for i,c in enumerate(C[p]):
            if not np.isnan(c): ts.append(i); ys.append(c)
    ts=np.array(ts,float); ys=np.array(ys)
    def f(th,t): return th[0]+th[1]*(1-np.exp(-np.maximum(t-th[3],0)/th[2]))
    r=least_squares(lambda th: f(th,ts)-ys, x0=[37.3,1.6,25,0], loss='soft_l1', f_scale=0.3)
    return r.x, f
for stat in ['mean','median']:
    for sm in [0,2,4]:
        maes=[]
        for p in people:
            tr=[q for q in people if q!=p]
            v=lookup_mean(tr,stat,sm)
            m=~np.isnan(C[p]); maes.append(np.mean(np.abs(v[m]-C[p][m])))
        print(stat,sm,round(np.mean(maes),4))
maes=[]; ths=[]
for p in people:
    tr=[q for q in people if q!=p]
    th,f=expfit(tr); ths.append(th)
    m=~np.isnan(C[p]); t=np.arange(60)[m]
    maes.append(np.mean(np.abs(f(th,t)-C[p][m])))
print('exp', round(np.mean(maes),4), np.round(np.mean(ths,0),3))
th,f=expfit(people); print('full exp params', np.round(th,4))
print([round(f(th,t),2) for t in [0,1,5,10,20,30,40,50,59]])
print('mean traj', np.round(lookup_mean(people,'mean',2),2).tolist())
