import pickle, numpy as np, itertools
from lopo import X,Y,people,mat,ridge_fit,ridge_pred
def backbone(e): return 37.4115+1.5938*(1-np.exp(-np.maximum(e-2.4113,0)/28.8934))
def lopo_res(names, lam):
    maes={}
    for p in people:
        tr=[q for q in people if q!=p]
        A,y=mat(names,tr); e=np.array([f['elapsed'] for q in tr for f in X[q]]); r=y-backbone(e)
        m=ridge_fit(A,r,lam)
        At,yt=mat(names,[p]); et=np.array([f['elapsed'] for f in X[p]])
        pr=backbone(et)+ridge_pred(m,At)
        maes[p]=np.mean(np.abs(pr-yt))
    return np.mean(list(maes.values())), maes
# baseline backbone only
maes={p:np.mean(np.abs(backbone(np.array([f['elapsed'] for f in X[p]]))-Y[p])) for p in people}
print('backbone', round(np.mean(list(maes.values())),4), {k:round(v,2) for k,v in maes.items()})
cands=['mass','bsa','mass_bsa','height','age','hr_int','hr_x_el','w_x_el','sk_x_el','sk_slope','sk_delta','hr_now','hr_mean','w_kg','sk_now','work_kg','amb','hum']
for c in cands:
    out=[]
    for lam in [30,100,300,1000]:
